/** Generates SDK types and validators from the Go protocol schema. Never edit the generated files by hand. */
import { execFile } from "node:child_process"
import { mkdir, readFile, writeFile } from "node:fs/promises"
import path from "node:path"
import { promisify } from "node:util"
import { format, resolveConfig } from "prettier"
import { z } from "zod"

type Node = {
  prefix?: string
  $ref?: string
  type?: string
  const?: string
  format?: string
  properties?: Record<string, Node>
  required?: string[]
  additionalProperties?: boolean | Node
  items?: Node
  anyOf?: Node[]
}

const node: z.ZodType<Node> = z.lazy(() =>
  z.object({
    $ref: z.string().optional(),
    type: z.string().optional(),
    const: z.string().optional(),
    format: z.string().optional(),
    properties: z.record(z.string(), node).optional(),
    required: z.array(z.string()).optional(),
    additionalProperties: z.union([z.boolean(), node]).optional(),
    items: node.optional(),
    anyOf: z.array(node).optional(),
  }),
)

const schema = z.object({
  $defs: z.record(z.string(), node),
  "x-protocol": z.number().int(),
  "x-methods": z.record(z.string(), z.object({ params: node, result: node })),
  "x-events": z.record(z.string(), node),
  "x-envelope": node,
})

const quote = JSON.stringify
const reference = (ref: string) => {
  if (!ref.startsWith("#/$defs/")) throw new Error("Unsupported schema reference")
  const name = ref.slice(8)
  if (!/^[A-Za-z][A-Za-z0-9]*$/.test(name)) throw new Error("Invalid schema definition name")
  return name
}

function typeOf(value: Node): string {
  if (value.prefix) return "`" + value.prefix.replace(/[`\\$]/g, "\\$&") + "${string}`"
  if (value.$ref) return reference(value.$ref)
  if (value.const !== undefined) return quote(value.const)
  if (value.anyOf) return value.anyOf.map(typeOf).join(" | ")
  if (value.type === "array") return `(${typeOf(value.items ?? {})})[]`
  if (value.type === "object") {
    if (typeof value.additionalProperties === "object") return `Record<string, ${typeOf(value.additionalProperties)}>`
    return `{ ${Object.entries(value.properties ?? {})
      .map(([key, child]) => `${quote(key)}${value.required?.includes(key) ? "" : "?"}: ${typeOf(child)}`)
      .join("; ")} }`
  }
  if (value.type === "integer" || value.type === "number") return "number"
  if (value.type === "string" || value.type === "boolean" || value.type === "null") return value.type
  return "unknown"
}

function validator(value: Node): string {
  if (value.prefix)
    return `z.custom<${typeOf(value)}>((value) => typeof value === "string" && value.startsWith(${quote(value.prefix)}) && value.length > ${value.prefix.length} && !/[\\p{White_Space}\\uFEFF\\u0000]/u.test(value))`
  if (value.$ref) return `${reference(value.$ref)}Schema`
  if (value.const !== undefined) return `z.literal(${quote(value.const)})`
  if (value.anyOf) return `z.union([${value.anyOf.map(validator).join(", ")}])`
  if (value.type === "array") return `z.array(${validator(value.items ?? {})})`
  if (value.type === "object") {
    if (typeof value.additionalProperties === "object")
      return `z.record(z.string(), ${validator(value.additionalProperties)})`
    return `z.strictObject({${Object.entries(value.properties ?? {})
      .map(([key, child]) => `${quote(key)}: ${validator(child)}${value.required?.includes(key) ? "" : ".optional()"}`)
      .join(", ")}})`
  }
  if (value.type === "integer") return "z.number().int()"
  if (value.type === "number" || value.type === "string" || value.type === "boolean" || value.type === "null")
    return `z.${value.type}()`
  return "z.unknown()"
}

export async function renderTypes(input: unknown): Promise<string> {
  const doc = schema.parse(input)
  const envelope = doc["$defs"][reference(doc["x-envelope"].$ref ?? "")]
  if (!envelope) throw new Error("Event envelope is missing")
  const events = Object.entries(doc["x-events"])
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([kind, payload]): Node => ({
      ...envelope,
      properties: {
        ...envelope.properties,
        type: kind === "external.*" ? { prefix: "external." } : { const: kind },
        payload,
      },
    }))
  const lines = [
    "// Generated by pnpm generate:protocol. Do not edit by hand.",
    'import { z } from "zod"',
    `export const PROTOCOL_VERSION = ${doc["x-protocol"]}`,
  ]
  for (const [name, value] of Object.entries(doc["$defs"]).sort(([a], [b]) => a.localeCompare(b))) {
    lines.push(
      `export type ${name} = ${typeOf(value)}`,
      `export const ${name}Schema: z.ZodType<${name}> = z.lazy(() => ${validator(value)})`,
    )
  }
  lines.push(`export type EngineEvent = ${events.map(typeOf).join(" | ")}`)
  lines.push(
    `export const EngineEventSchema: z.ZodType<EngineEvent> = ${events.length === 1 ? validator(events[0]!) : `z.union([${events.map(validator).join(", ")}])`}`,
  )
  const methods = Object.entries(doc["x-methods"]).sort(([a], [b]) => a.localeCompare(b))
  lines.push(
    `export type Methods = {${methods.map(([name, method]) => `${quote(name)}: { params: ${typeOf(method.params)}; result: ${typeOf(method.result)} }`).join("; ")}}`,
  )
  lines.push(
    `export const methodSchemas = {${methods.map(([name, method]) => `${quote(name)}: { params: ${validator(method.params)}, result: ${validator(method.result)} }`).join(", ")}}`,
  )
  return format(lines.join("\n"), { parser: "typescript", semi: false, printWidth: 120 })
}

export async function saveGenerated(file: string, text: string, check: boolean) {
  if (check) {
    const current = await readFile(file, "utf8").catch(() => "")
    if (current.replaceAll("\r\n", "\n") !== text) throw new Error(`${file} is out of date; run pnpm generate:protocol`)
    return
  }
  await mkdir(path.dirname(file), { recursive: true })
  await writeFile(file, text)
}

async function main() {
  const root = path.resolve(import.meta.dirname, "..")
  const { stdout } = await promisify(execFile)("go", ["run", "./protocol/gen"], {
    cwd: path.join(root, "merak"),
    maxBuffer: 8 << 20,
  })
  const json = schema.parse(JSON.parse(stdout))
  const schemaFile = path.join(root, "schema", "protocol.json")
  const config = await resolveConfig(schemaFile)
  const check = process.argv.includes("--check")
  await saveGenerated(schemaFile, await format(stdout, { ...config, filepath: schemaFile }), check)
  await saveGenerated(path.join(root, "packages", "sdk", "src", "protocol.gen.ts"), await renderTypes(json), check)
}

if (import.meta.main) await main()
